Docs.remarks:
Minimal conversion of a Microsoft 365 Agents SDK Program.cs:

var builder = WebApplication.CreateBuilder(args);
builder.AddAgent<MyAgent>();                          // unchanged (MyAgent : AgentApplication)
builder.Services.AddSingleton<IStorage, MemoryStorage>(); // unchanged
builder.AddFoundryActivity();                          // was: AddAgentAspNetAuthentication(Configuration)

var app = builder.Build();
app.MapFoundryActivity();                              // was: UseAuthentication/Authorization + MapAgentApplicationEndpoints
app.Run();
